class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        if abs(target) > total or (total + target) % 2:
            return 0
        want = (total + target) // 2   # sum of the elements that receive a plus sign
        dp = [0] * (want + 1)
        dp[0] = 1
        for x in nums:
            for s in range(want, x - 1, -1):   # downward: each element used at most once
                dp[s] += dp[s - x]
        return dp[want]

